{"code": "const [q1,q2,q3] = await Promise.all([
  tools.pwsh({description: "Search dag for S1950", command: "Select-String -Path D:\\lean\\dag\\*,D:\\lean\\coord\\* -Pattern 'S1950' -SimpleMatch | Select-Object -First 40 Path,LineNumber,Line | Format-List", workdir: "D:\\lean"}),
  tools.pwsh({description: "Search audit ledger archimedean", command: "Select-String -Path D:\\lean\\AUDIT_LEDGER.md -Pattern 'archimedean|Archimedean|S1927' | Select-Object -First 60 LineNumber,Line | Format-List", workdir: "D:\\lean"}),
  tools.pwsh({description: "List dag dir", command: "Get-ChildItem D:\\lean\\dag | Select-Object Name,Length | Format-Table -AutoSize", workdir: "D:\\lean"})
]);
console.log("== S1950 refs ==");
console.log(q1.stdout.text);
console.log("== ledger ==");
console.log(q2.stdout.text);
